20: /**
21:  * Test case for the PosixParser.
22:  *
23:  * @version $Revision$, $Date$
24:  */
25: public class PosixParserTest extends ParserTestCase
26: {
27:     public void setUp()
28:     {
29:         super.setUp();
30:         parser = new PosixParser();
31:     }
32: 
33:     public void testBursting() throws Exception
34:     {
35:         String[] args = new String[] { "-acbtoast",
36:                                        "foo", "bar" };
37: 
38:         CommandLine cl = parser.parse(options, args);
39: 
40:         assertTrue( "Confirm -a is set", cl.hasOption("a") );
41:         assertTrue( "Confirm -b is set", cl.hasOption("b") );
42:         assertTrue( "Confirm -c is set", cl.hasOption("c") );
43:         assertTrue( "Confirm arg of -b", cl.getOptionValue("b").equals("toast") );
44:         assertTrue( "Confirm size of extra args", cl.getArgList().size() == 2);
45:     }
46: 
47:     public void testUnrecognizedOptionWithBursting() throws Exception
48:     {
49:         String[] args = new String[] { "-adbtoast", "foo", "bar" };
50: 
51:         try
52:         {
53:             parser.parse(options, args);
54:             fail("UnrecognizedOptionException wasn't thrown");
55:         }
56:         catch (UnrecognizedOptionException e)
57:         {
58:             assertEquals("-adbtoast", e.getOption());
59:         }
60:     }
